  1 | import { useCallback, useMemo, useRef, useState } from "react";
  2 | import type { Track } from "../types";
  3 | 
  4 | interface PlaylistProps {
  5 |   tracks: Track[];
  6 |   currentTrackId: string | null;
  7 |   isPlaying: boolean;
  8 |   onSelectTrack: (track: Track) => void;
  9 |   onReorderPlaylist?: (tracks: Track[]) => void;
 10 |   onDropFiles?: (files: FileList) => void;
 11 |   onToggleFavorite?: (trackId: string) => void;
 12 | }
 13 | 
 14 | function formatDuration(seconds: number): string {
 15 |   const mins = Math.floor(seconds / 60);
 16 |   const secs = Math.floor(seconds % 60);
 17 |   return `${mins}:${secs.toString().padStart(2, "0")}`;
 18 | }
 19 | 
 20 | function normalizeText(text: string): string {
 21 |   return text
 22 |     .normalize("NFD")
 23 |     .replace(/[\u0300-\u036f]/g, "")
 24 |     .toLowerCase();
 25 | }
 26 | 
 27 | export function Playlist({
 28 |   tracks,
 29 |   currentTrackId,
 30 |   isPlaying,
 31 |   onSelectTrack,
 32 |   onReorderPlaylist,
 33 |   onDropFiles,
 34 |   onToggleFavorite,
 35 | }: PlaylistProps) {
 36 |   const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
 37 |   const dragItemIndex = useRef<number | null>(null);
 38 |   const [isDragOver, setIsDragOver] = useState(false);
 39 |   const [searchQuery, setSearchQuery] = useState("");
 40 | 
 41 |   // Filtro de busca
 42 |   const normalizedQuery = normalizeText(searchQuery);
 43 | 
 44 |   const filteredTracks = useMemo(() => {
 45 |     if (!normalizedQuery) return tracks;
 46 |     return tracks.filter((track) => {
 47 |       const title = normalizeText(track.title);
 48 |       const artist = track.artist ? normalizeText(track.artist) : "";
 49 |       return title.includes(normalizedQuery) || artist.includes(normalizedQuery);
 50 |     });
 51 |   }, [tracks, normalizedQuery]);
 52 | 
 53 |   // Mapeia índice filtrado → índice original para drag & drop
 54 |   const filteredToOriginalIndex = useMemo(() => {
 55 |     if (!normalizedQuery) return null;
 56 |     return filteredTracks.map((ft) => tracks.indexOf(ft));
 57 |   }, [filteredTracks, tracks, normalizedQuery]);
 58 | 
 59 |   // Drag & drop de arquivos do sistema
 60 |   const handleDragOverWindow = useCallback((e: React.DragEvent) => {
 61 |     if (e.dataTransfer.types.includes("Files")) {
 62 |       e.preventDefault();
 63 |       e.stopPropagation();
 64 |       setIsDragOver(true);
 65 |     }
 66 |   }, []);
 67 | 
 68 |   const handleDragLeaveWindow = useCallback((e: React.DragEvent) => {
 69 |     e.preventDefault();
 70 |     setIsDragOver(false);
 71 |   }, []);
 72 | 
 73 |   const handleDropWindow = useCallback(
 74 |     (e: React.DragEvent) => {
 75 |       e.preventDefault();
 76 |       e.stopPropagation();
 77 |       setIsDragOver(false);
 78 | 
 79 |       if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
 80 |         onDropFiles?.(e.dataTransfer.files);
 81 |       }
 82 |     },
 83 |     [onDropFiles]
 84 |   );
 85 | 
 86 |   const resolveOriginalIndex = useCallback(
 87 |     (filteredIndex: number): number => {
 88 |       if (filteredToOriginalIndex) {
 89 |         return filteredToOriginalIndex[filteredIndex];
 90 |       }
 91 |       return filteredIndex;
 92 |     },
 93 |     [filteredToOriginalIndex]
 94 |   );
 95 | 
 96 |   const handleDragStart = useCallback(
 97 |     (e: React.DragEvent<HTMLLIElement>, filteredIndex: number) => {
 98 |       const originalIndex = resolveOriginalIndex(filteredIndex);
 99 |       dragItemIndex.current = originalIndex;
100 |       e.dataTransfer.effectAllowed = "move";
101 |       e.dataTransfer.setData("text/plain", String(originalIndex));
102 |       // Add a slight delay so the drag image shows properly
103 |       e.currentTarget.classList.add("dragging");
104 |     },
105 |     [resolveOriginalIndex]
106 |   );
107 | 
108 |   const handleDragEnd = useCallback(
109 |     (e: React.DragEvent<HTMLLIElement>) => {
110 |       e.currentTarget.classList.remove("dragging");
111 |       dragItemIndex.current = null;
112 |       setDragOverIndex(null);
113 |     },
114 |     []
115 |   );
116 | 
117 |   const handleDragOver = useCallback(
118 |     (e: React.DragEvent<HTMLLIElement>, filteredIndex: number) => {
119 |       e.preventDefault();
120 |       e.dataTransfer.dropEffect = "move";
121 |       setDragOverIndex(filteredIndex);
122 |     },
123 |     []
124 |   );
125 | 
126 |   const handleDragLeave = useCallback(() => {
127 |     setDragOverIndex(null);
128 |   }, []);
129 | 
130 |   const handleDrop = useCallback(
131 |     (e: React.DragEvent<HTMLLIElement>, dropFilteredIndex: number) => {
132 |       e.preventDefault();
133 |       const fromIndex = dragItemIndex.current;
134 |       const dropIndex = resolveOriginalIndex(dropFilteredIndex);
135 |       if (fromIndex === null || fromIndex === dropIndex) {
136 |         setDragOverIndex(null);
137 |         return;
138 |       }
139 | 
140 |       const reordered = [...tracks];
141 |       const [movedItem] = reordered.splice(fromIndex, 1);
142 |       reordered.splice(dropIndex, 0, movedItem);
143 | 
144 |       onReorderPlaylist?.(reordered);
145 |       dragItemIndex.current = null;
146 |       setDragOverIndex(null);
147 |     },
148 |     [tracks, onReorderPlaylist, resolveOriginalIndex]
149 |   );
150 | 
151 |   return (
152 |     <section
153 |       className={`playlist-panel ${isDragOver ? "playlist-drag-over" : ""}`}
154 |       onDragOver={handleDragOverWindow}
155 |       onDragLeave={handleDragLeaveWindow}
156 |       onDrop={handleDropWindow}
157 |     >
158 |       <div className="panel-header">PLAYLIST</div>
159 |       {isDragOver && (
160 |         <div className="playlist-drop-indicator">
161 |           📁 Solte os arquivos para adicionar à playlist
162 |         </div>
163 |       )}
164 |       <div className="playlist-search-container">
165 |         <input
166 |           type="text"
167 |           className="playlist-search-input"
168 |           placeholder="Buscar música..."
169 |           value={searchQuery}
170 |           onChange={(e) => setSearchQuery(e.target.value)}
171 |           aria-label="Buscar música na playlist"
172 |         />
173 |         {searchQuery && (
174 |           <button
175 |             className="playlist-search-clear"
176 |             onClick={() => setSearchQuery("")}
177 |             title="Limpar busca"
178 |             aria-label="Limpar busca"
179 |           >
180 |             ✕
181 |           </button>
182 |         )}
183 |       </div>
184 |       {searchQuery && (
185 |         <div className="playlist-search-count">
186 |           {filteredTracks.length === 0
187 |             ? "Nenhuma música encontrada"
188 |             : `${filteredTracks.length} de ${tracks.length} música${tracks.length !== 1 ? "s" : ""}`}
189 |         </div>
190 |       )}
191 |       <ul className="playlist">
192 |         {tracks.length === 0 ? (
193 |           <li className="playlist-item playlist-empty">
194 |             Nenhuma música na playlist
195 |           </li>
196 |         ) : filteredTracks.length === 0 ? (
197 |           <li className="playlist-item playlist-empty">
198 |             Nenhuma música encontrada
199 |           </li>
200 |         ) : (
201 |           filteredTracks.map((track, filteredIndex) => (
202 |             <li
203 |               key={track.id}
204 |               className={`playlist-item ${
205 |                 track.id === currentTrackId ? "active" : ""
206 |               } ${dragOverIndex === filteredIndex ? "drag-over" : ""}`}
207 |               draggable
208 |               onClick={() => onSelectTrack(track)}
209 |               onDragStart={(e) => handleDragStart(e, filteredIndex)}
210 |               onDragEnd={handleDragEnd}
211 |               onDragOver={(e) => handleDragOver(e, filteredIndex)}
212 |               onDragLeave={handleDragLeave}
213 |               onDrop={(e) => handleDrop(e, filteredIndex)}
214 |               title={`${track.title}${track.artist ? ` — ${track.artist}` : ""}`}
215 |             >
216 |               <span className="playlist-item-drag-handle" title="Arrastar para reordenar">
217 |                 ⠿
218 |               </span>
219 |               {onToggleFavorite && (
220 |                 <span
221 |                   className={`playlist-item-favorite ${track.isFavorite ? "favorite-active" : ""}`}
222 |                   onClick={(e) => {
223 |                     e.stopPropagation();
224 |                     onToggleFavorite(track.id);
225 |                   }}
226 |                   title={track.isFavorite ? "Remover dos favoritos" : "Adicionar aos favoritos"}
227 |                 >
228 |                   {track.isFavorite ? "♥" : "♡"}
229 |                 </span>
230 |               )}
231 |               <span className="playlist-item-icon">
232 |                 {track.id === currentTrackId && isPlaying ? "▶" : "🎵"}
233 |               </span>
234 |               <span className="playlist-item-title">{track.title}</span>
235 |               {track.artist && (
236 |                 <span className="playlist-item-artist">{track.artist}</span>
237 |               )}
238 |               <span className="playlist-item-duration">
239 |                 {formatDuration(track.duration)}
240 |               </span>
241 |             </li>
242 |           ))
243 |         )}
244 |       </ul>
245 |       <div className="panel-footer">
246 |         <span>{tracks.length} música{tracks.length !== 1 ? "s" : ""}</span>
247 |         <span>
248 |           {tracks.reduce((acc, t) => acc + t.duration, 0) > 0
249 |             ? formatDuration(tracks.reduce((acc, t) => acc + t.duration, 0))
250 |             : "—:—:—"}
251 |         </span>
252 |       </div>
253 |     </section>
254 |   );
255 | }
